function buildTrust(){var byTrader=new Map(),byToken=new Map();state.events.forEach(function(e){if(!e.addr)return;if(!byTrader.has(e.traderLc))byTrader.set(e.traderLc,[]);byTrader.get(e.traderLc).push(e);if(!byToken.has(e.addr))byToken.set(e.addr,[]);byToken.get(e.addr).push(e);});var map=new Map();byTrader.forEach(function(evs,tr){evs.sort(function(a,b){return a.ts-b.ts;});var rt=0,flips=0,dumps=0,sells=0;evs.forEach(function(e,idx){if(e.type==='buy'){for(var k=idx+1;k<evs.length;k++)if(evs[k].addr===e.addr&&evs[k].type==='sell'){rt++;if(evs[k].ts-e.ts<=FLIP_MS)flips++;break;}}else{sells++;var others=new Set();(byToken.get(e.addr)||[]).forEach(function(o){if(o.type==='buy'&&o.traderLc!==tr&&o.ts>=e.ts-DUMP_LOOKBACK_MS&&o.ts<=e.ts)others.add(o.traderLc);});if(others.size>=2)dumps++;}});var prov=rt<3,flipRate=rt?flips/rt:0,dumpRate=sells?dumps/sells:0;var sc=1-0.5*flipRate-0.55*dumpRate;if(prov)sc=0.6+(sc-0.6)*0.4;map.set(tr,{score:Math.max(0.05,Math.min(1,sc)),provisional:prov,flips:flips,dumps:dumps,rt:rt,sells:sells});});trustCache={at:Date.now(),map:map};}
