function computeTrenches(){var now=Date.now(),out=[];groupWindow().forEach(function(g){var qAll=g.buys.filter(function(e){return state.leaders.has(e.traderLc);});if(!qAll.length)return;var en=state.enrich.get(g.addr);if(!trenchYoungSmall(en))return;var perT=new Map();qAll.forEach(function(e){var p=perT.get(e.traderLc);if(!p||(e.usd||0)>(p.usd||0))perT.set(e.traderLc,e);});var buyers=Array.from(perT.values());var lastBuyTs=buyers.reduce(function(m,e){return Math.max(m,e.ts);},0);var firstBuyTs=buyers.reduce(function(m,e){return Math.min(m,e.ts);},now);var freshness=Math.pow(0.5,((now-lastBuyTs)/60000)/20);var bestRank=buyers.reduce(function(m,e){return Math.min(m,state.leaders.get(e.traderLc).rank||999);},999);var qBuyUsd=buyers.reduce(function(s,e){return s+(e.usd||0);},0);var convN=0;buyers.forEach(function(e){var m=medBuyUsd(e.traderLc);convN+=(m&&e.usd)?Math.min(2.5,e.usd/m):1;});var conviction=convN/buyers.length;var sf=state.safety.get(g.addr);var early=Math.pow(Math.min(1,buyers.length/3),0.55)*(0.7+0.3*(bestRank<=40?1:bestRank<=80?0.5:0))*(0.85+0.3*Math.min(1,(conviction-0.9)/0.9))*freshness;var comm=communityScore(en,null),vir=viralityScore(en,sf),sfac=safetyFactor(sf);var pc=(en&&en.pc)||{};var ran=pc.h1!=null?pc.h1:0;var lateCut=ran>=900?0.3:ran>=400?0.6:ran>=180?0.85:1;var score=Math.round(100*(0.28+0.72*early)*(0.35+0.65*comm)*(0.3+0.7*vir)*sfac*lateCut);out.push({addr:g.addr,token:g.token,chain:g.chain,en:en,sf:sf,buyers:buyers,distinctQ:buyers.length,bestRank:bestRank,qBuyUsd:qBuyUsd,conviction:conviction,comm:comm,vir:vir,sfac:sfac,ran:ran,spanMin:(lastBuyTs-firstBuyTs)/60000,score:score,blocked:sf&&sf.ok===false,disc:false,mode:'trenches'});});(state._discRaw||[]).forEach(function(d){if(out.some(function(o){return o.addr===d.addr;}))return;var en=state.enrich.get(d.addr);if(!trenchYoungSmall(en))return;var sf=state.safety.get(d.addr);var comm=communityScore(en,d.links),vir=viralityScore(en,sf),sfac=safetyFactor(sf);if(comm<0.35)return;var pc=(en&&en.pc)||{};var ran=pc.h1!=null?pc.h1:0;var lateCut=ran>=900?0.3:ran>=400?0.6:ran>=180?0.85:1;var score=Math.round(100*0.6*(0.35+0.65*comm)*(0.3+0.7*vir)*sfac*lateCut);out.push({addr:d.addr,token:(en&&en.sym)||'?',chain:d.chain,en:en,sf:sf,buyers:[],distinctQ:0,bestRank:999,qBuyUsd:0,conviction:0,comm:comm,vir:vir,sfac:sfac,ran:ran,spanMin:0,score:score,blocked:sf&&sf.ok===false,disc:true,mode:'trenches'});});out.sort(function(a,b){return b.score-a.score;});return out;}
function modelSize(s){if(s.mode==='trenches'){var f=0.005+0.02*Math.min(1,Math.max(0,(s.score-45)/45));f*=s.sfac>=0.9?1:0.7;if(s.en&&s.en.liqUsd)f=Math.min(f,(0.003*s.en.liqUsd)/Math.max(1,state.bankroll));f=Math.max(0,Math.min(0.03,f));return{frac:f,usd:f*state.bankroll};}var g=0.02+0.05*Math.min(1,Math.max(0,(s.score-55)/40));g*=(0.6+0.4*s.trustAvg);if(s.liq)g=Math.min(g,(0.01*s.liq)/Math.max(1,state.bankroll));g=Math.max(0,Math.min(0.08,g));return{frac:g,usd:g*state.bankroll};}
function pushAlert(c){var hook=state.hook;if(!hook)return;var txt=(state.mode==='trenches'?'TRENCH ':'')+'CALL $'+c.token+' | '+c.chain+' | score '+c.score+' | https://dexscreener.com/search?q='+c.addr;try{if(/^tg:/i.test(hook)){var p=hook.slice(3).split(':');if(p.length>=2)fetch('https://api.telegram.org/bot'+p[0]+'/sendMessage?chat_id='+encodeURIComponent(p.slice(1).join(':'))+'&text='+encodeURIComponent(txt)).catch(function(){});}else if(/^https?:\/\//i.test(hook)){fetch(hook,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({content:txt,text:txt})}).catch(function(){});}}catch(_){}}
function evalCall(list){var now=Date.now(),changed=false;state.calls.forEach(function(c){if(c.status!=='open')return;var en=state.enrich.get(c.addr);var px=en&&en.priceUsd?en.priceUsd:null;if(px&&c.entryPx){c.lastPx=px;c.retPct=(px/c.entryPx-1)*100;}if(now-c.ts>6*60*60*1000){c.status='closed';changed=true;}});var top;if(state.mode==='trenches'){top=list.filter(function(s){return !s.blocked&&s.sf&&s.sf.ok===true&&s.distinctQ>=1&&s.score>=TR_CALL_SCORE;})[0];}else{top=list.filter(function(s){return (s.liqOk||s.liqUnknown)&&!s.netNegative&&s.score>=CALL_MIN_SCORE&&s.distinctQ>=CALL_MIN_BUYERS&&!s.liqUnknown;})[0];}if(top){var ex=state.calls.filter(function(c){return c.status==='open'&&c.addr===top.addr;})[0];if(!ex){var en=state.enrich.get(top.addr);var nc={id:'c_'+now+'_'+top.addr.slice(0,6),addr:top.addr,token:top.token,chain:top.chain,ts:now,mode:state.mode,score:top.score,buyers:top.distinctQ,entryPx:en&&en.priceUsd?en.priceUsd:0,lastPx:en&&en.priceUsd?en.priceUsd:0,retPct:0,status:'open'};state.calls.push(nc);changed=true;maybeNotify(top);pushAlert(nc);}}if(changed)saveCalls();return top||null;}
