function fitCanvas(cv){var dpr=window.devicePixelRatio||1,w=cv.clientWidth||cv.parentNode.clientWidth||600,h=cv.clientHeight||160;cv.width=Math.max(1,Math.round(w*dpr));cv.height=Math.max(1,Math.round(h*dpr));var x=cv.getContext('2d');x.setTransform(dpr,0,0,dpr,0,0);return {x:x,w:w,h:h};}
function drawChart(cv,rows){if(!cv)return;var c=fitCanvas(cv),x=c.x,w=c.w,h=c.h;x.clearRect(0,0,w,h);if(!rows||rows.length<2){x.fillStyle=cssv('--ink-faint');x.font='13px "Patrick Hand",cursive';x.fillText('chart loading / not indexed yet',10,h/2);return;}var cl=rows.map(function(r){return +r[4];});var lo=Math.min.apply(null,cl),hi=Math.max.apply(null,cl);var pad=(hi-lo)*0.14||hi*0.05||1;lo-=pad;hi+=pad;var px=function(i){return 6+i/(rows.length-1)*(w-12);};var py=function(v){return h-8-(v-lo)/(hi-lo||1)*(h-24);};var up=cl[cl.length-1]>=cl[0];var col=up?cssv('--pos'):cssv('--neg');x.beginPath();x.moveTo(px(0),py(cl[0]));for(var i=1;i<cl.length;i++)x.lineTo(px(i),py(cl[i]));x.lineTo(px(cl.length-1),h-8);x.lineTo(px(0),h-8);x.closePath();x.fillStyle=up?'rgba(47,124,77,.14)':'rgba(165,48,28,.13)';x.fill();x.beginPath();x.moveTo(px(0),py(cl[0]));for(var j=1;j<cl.length;j++)x.lineTo(px(j),py(cl[j]));x.strokeStyle=col;x.lineWidth=2;x.stroke();x.beginPath();x.arc(px(cl.length-1),py(cl[cl.length-1]),3,0,7);x.fillStyle=col;x.fill();x.fillStyle=cssv('--ink-faint');x.font='11px "Patrick Hand",cursive';x.fillText(fPrice(hi),6,12);x.fillText(fPrice(lo),6,h-12);x.textAlign='right';x.fillStyle=col;x.fillText(fPct((cl[cl.length-1]/cl[0]-1)*100)+' / '+rows.length*5+'m',w-6,12);x.textAlign='left';}
function drawSeries(cv,pts){if(!cv)return;var c=fitCanvas(cv),x=c.x,w=c.w,h=c.h;x.clearRect(0,0,w,h);if(!pts||pts.length<2){x.fillStyle=cssv('--ink-faint');x.font='13px "Patrick Hand",cursive';x.fillText('not enough closed trades yet',10,h/2);return;}var vs=pts.map(function(p){return p.v;});var lo=Math.min(0,Math.min.apply(null,vs)),hi=Math.max.apply(null,vs)||1;var px=function(i){return 6+i/(pts.length-1)*(w-12);};var py=function(v){return h-8-(v-lo)/(hi-lo||1)*(h-20);};var col=vs[vs.length-1]>=0?cssv('--pos'):cssv('--neg');x.strokeStyle=cssv('--pencil');x.beginPath();x.moveTo(6,py(0));x.lineTo(w-6,py(0));x.stroke();x.beginPath();x.moveTo(px(0),py(vs[0]));for(var i=1;i<vs.length;i++)x.lineTo(px(i),py(vs[i]));x.strokeStyle=col;x.lineWidth=2;x.stroke();x.fillStyle=col;x.font='11px "Patrick Hand",cursive';x.fillText(fUsd(vs[vs.length-1])+' realized (feed)',8,14);}
function drawBubble(cv,arr){if(!cv)return;var c=fitCanvas(cv),x=c.x,w=c.w,h=c.h;x.clearRect(0,0,w,h);state._bhits=[];if(!arr.length){x.fillStyle=cssv('--ink-faint');x.font='14px "Patrick Hand",cursive';x.fillText('leaderboard loading...',12,h/2);return;}var pad={l:52,r:14,t:14,b:26};var lx=function(v){return Math.log10(Math.max(1,v));};var mxT=Math.max.apply(null,arr.map(function(a){return lx((a.trades||1));}));var mnP=Math.min.apply(null,arr.map(function(a){return a.pnlUsd;}));var mxP=Math.max.apply(null,arr.map(function(a){return a.pnlUsd;}));var sp=function(v){return v>=0?Math.log10(1+v):-Math.log10(1-v);};var mnS=sp(mnP),mxS=sp(mxP);var X=function(t){return pad.l+(lx(t)/(mxT||1))*(w-pad.l-pad.r);};var Y=function(p){return h-pad.b-((sp(p)-mnS)/((mxS-mnS)||1))*(h-pad.t-pad.b);};x.strokeStyle=cssv('--pencil');x.lineWidth=1;x.beginPath();x.moveTo(pad.l,h-pad.b);x.lineTo(w-pad.r,h-pad.b);x.moveTo(pad.l,pad.t);x.lineTo(pad.l,h-pad.b);x.stroke();x.fillStyle=cssv('--ink-faint');x.font='10px "Patrick Hand",cursive';x.fillText('trades ->',pad.l,h-8);x.save();x.translate(12,pad.t+40);x.rotate(-Math.PI/2);x.fillText('board PnL ->',0,0);x.restore();var y0=Y(0);x.strokeStyle='rgba(120,110,80,.25)';x.beginPath();x.moveTo(pad.l,y0);x.lineTo(w-pad.r,y0);x.stroke();arr.forEach(function(a){var cx=X(a.trades||1),cy=Y(a.pnlUsd);var r=4+Math.sqrt(Math.max(0,a.followers))/40;r=Math.max(4,Math.min(26,r));x.beginPath();x.arc(cx,cy,r,0,7);x.fillStyle=trustCol(a.prov?null:a.trust);x.globalAlpha=.7;x.fill();x.globalAlpha=1;x.lineWidth=1.5;x.strokeStyle=cssv('--ink');x.stroke();state._bhits.push({x:cx,y:cy,r:r+3,h:a.h});});var top=arr.slice().sort(function(p,q){return q.pnlUsd-p.pnlUsd;}).slice(0,5);x.fillStyle=cssv('--ink');x.font='11px "Patrick Hand",cursive';top.forEach(function(a){x.fillText('@'+a.name,X(a.trades||1)+6,Y(a.pnlUsd)-6);});}
function drawNet2d(cv,g){if(!cv)return;var c=fitCanvas(cv),x=c.x,w=c.w,h=c.h;x.fillStyle='#12131c';x.fillRect(0,0,w,h);state._nhits=[];if(!g.nodes.length){x.fillStyle='#cdd2df';x.font='14px "Patrick Hand",cursive';x.fillText('no ranked buys in the window yet',14,h/2);return;}var N=g.nodes,L=g.links;var pos={};N.forEach(function(n,i){pos[n.id]={x:w/2+Math.cos(i)*120+(Math.random()-.5)*40,y:h/2+Math.sin(i*1.7)*120+(Math.random()-.5)*40,vx:0,vy:0};});for(var it=0;it<90;it++){for(var i=0;i<N.length;i++){for(var j=i+1;j<N.length;j++){var a=pos[N[i].id],b=pos[N[j].id];var dx=a.x-b.x,dy=a.y-b.y,d2=dx*dx+dy*dy+0.01;var f=1400/d2;a.vx+=dx*f;a.vy+=dy*f;b.vx-=dx*f;b.vy-=dy*f;}}L.forEach(function(l){var a=pos[l.source],b=pos[l.target];if(!a||!b)return;var dx=b.x-a.x,dy=b.y-a.y;a.vx+=dx*0.012;a.vy+=dy*0.012;b.vx-=dx*0.012;b.vy-=dy*0.012;});for(var k=0;k<N.length;k++){var p=pos[N[k].id];p.x+=(p.vx*=0.82);p.y+=(p.vy*=0.82);p.x=Math.max(16,Math.min(w-16,p.x));p.y=Math.max(16,Math.min(h-16,p.y));}}x.strokeStyle='rgba(200,200,220,.22)';x.lineWidth=1;L.forEach(function(l){var a=pos[l.source],b=pos[l.target];if(!a||!b)return;x.beginPath();x.moveTo(a.x,a.y);x.lineTo(b.x,b.y);x.stroke();});N.forEach(function(n){var p=pos[n.id];var r=n.group==='trader'?7:4+Math.min(10,n.val);x.beginPath();x.arc(p.x,p.y,r,0,7);x.fillStyle=n.group==='trader'?'#f2a63d':'#8ab6ff';x.fill();if(n.group==='trader'){x.fillStyle='#e7e9ee';x.font='10px "Patrick Hand",cursive';x.fillText(n.label,p.x+r+2,p.y+3);state._nhits.push({x:p.x,y:p.y,r:r+4,h:n.id.slice(2)});}});}
function buildGraph(){var now=Date.now(),nodes={},links=[];state.events.forEach(function(e){if(e.type!=='buy'||!e.addr||now-e.ts>WINDOW_MS||!state.leaders.has(e.traderLc)||!chainAllowed(e.chain))return;var tid='t:'+e.traderLc,kid='k:'+e.addr;if(!nodes[tid])nodes[tid]={id:tid,label:'@'+(state.leaders.get(e.traderLc).displayName||e.traderLc),group:'trader',val:6};if(!nodes[kid])nodes[kid]={id:kid,label:'$'+e.token,group:'token',val:3};nodes[kid].val=Math.min(16,nodes[kid].val+1);links.push({source:tid,target:kid});});return {nodes:Object.keys(nodes).map(function(k){return nodes[k];}),links:links};}
function mount3d(){var el=document.getElementById('net3d');var hint=document.getElementById('net3dHint');var g=buildGraph();if(state.netDim!=='3d'){return;}if(typeof window.ForceGraph3D==='undefined'){hint.textContent='3D lib blocked - showing 2D';state.netDim='2d';document.querySelector('[data-net="2d"]').setAttribute('aria-pressed','true');document.querySelector('[data-net="3d"]').setAttribute('aria-pressed','false');document.getElementById('net3d').hidden=true;var cv=document.getElementById('net2d');cv.hidden=false;drawNet2d(cv,g);return;}hint.textContent=g.nodes.length?'drag to rotate - scroll to zoom - click a trader':'no ranked buys in the window yet';if(!state._fg){state._fg=window.ForceGraph3D()(el).backgroundColor('#12131c').nodeLabel('label').nodeVal('val').nodeColor(function(n){return n.group==='trader'?'#f2a63d':'#8ab6ff';}).linkColor(function(){return 'rgba(200,200,220,.28)';}).linkOpacity(0.35).onNodeClick(function(n){if(n.group==='trader'){selectTab('traders');openTrader(n.id.slice(2));}});}state._fg.width(el.clientWidth).height(el.clientHeight).graphData(g);}
function traderStats(){var m=new Map();state.leaders.forEach(function(L,h){m.set(h,{h:h,name:L.displayName||L.handle,rank:L.rank,pnlUsd:L.pnlUsd,volumeUsd:L.volumeUsd,followers:L.followers,trades:L.trades,buys:0,sells:0,realized:0,tokens:new Set(),last:0,series:[]});});var evs=state.events.slice().sort(function(a,b){return a.ts-b.ts;});evs.forEach(function(e){var a=m.get(e.traderLc);if(!a)return;if(e.type==='buy')a.buys++;else{a.sells++;if(e.usd){a.realized+=e.usd;a.series.push({t:e.ts,v:a.realized});}}if(e.addr)a.tokens.add(e.addr);a.last=e.ts;});m.forEach(function(a){var tr=trustFor(a.h);a.trust=tr.score;a.prov=tr.provisional;a.flip=tr.rt?tr.flips/tr.rt:0;a.dumpRate=tr.sells?tr.dumps/tr.sells:0;a.rt=tr.rt;a.dumps=tr.dumps;a.feedTrades=a.buys+a.sells;a.verdict=a.prov?'watch':a.trust>=0.75?'copy':a.trust>=0.5?'careful':'avoid';});return Array.from(m.values()).filter(function(a){return a.rank!=null;});}
function renderTraders(){var arr=traderStats();var key=state.tsort;arr.sort(function(a,b){var x=a[key],y=b[key];if(key==='name'||key==='verdict')return String(x).localeCompare(String(y));return (y||0)-(x||0);});drawBubble(document.getElementById('tbubble'),arr);var cols=[['name','trader'],['rank','#'],['pnlUsd','board pnl'],['followers','followers'],['feedTrades','feed tr'],['realized','realized(feed)'],['flip','fast-flip'],['dumpRate','dump-flow'],['trust','trust'],['verdict','verdict']];var html='<table><thead><tr>'+cols.map(function(c){return '<th data-sort="'+c[0]+'">'+c[1]+(state.tsort===c[0]?' ▾':'')+'</th>';}).join('')+'</tr></thead><tbody>';arr.slice(0,60).forEach(function(a){var vc=a.verdict==='copy'?cssv('--pos'):a.verdict==='avoid'?cssv('--neg'):cssv('--accent');html+='<tr data-h="'+esc(a.h)+'"><td class="h">@'+esc(a.name)+'</td><td>'+a.rank+'</td><td>'+fUsd(a.pnlUsd)+'</td><td>'+fNum(a.followers)+'</td><td>'+a.feedTrades+'</td><td>'+fUsd(a.realized)+'</td><td>'+(a.rt?Math.round(a.flip*100)+'%':'-')+'</td><td>'+(a.sells?Math.round(a.dumpRate*100)+'%':'-')+'</td><td>'+(a.prov?'prov':a.trust.toFixed(2))+'</td><td style="color:'+vc+'">'+a.verdict+'</td></tr>';});html+='</tbody></table>';document.getElementById('ttable').innerHTML=html;if(state.trader)renderDrill(arr);}
