function selectTab(t){state.tab=t;saveCfg();document.querySelectorAll('.tab').forEach(function(b){b.setAttribute('aria-selected',b.getAttribute('data-tab')===t?'true':'false');});['signals','traders','network'].forEach(function(n){document.getElementById('view-'+n).hidden=n!==t;});render();if(t==='network')setTimeout(function(){state.netDim==='3d'?mount3d():drawNet2d(document.getElementById('net2d'),buildGraph());},60);}
